#!/usr/bin/env node
// The iOS widget and Apple Watch targets must be wired into the Xcode project,
// and the one file that defines them is regenerated by `tauri ios init`
// (myne-md/myne#803).
//
// # The failure this prevents
//
// `mobile/src-tauri/gen/apple/` is git-ignored and `tauri ios init` rebuilds it
// wholesale. The widget extension, the watch app + complication and the
// WatchConnectivity receiver were wired only by hand-editing
// `gen/apple/project.yml`, with the re-apply step living in a README sentence.
// So a fresh init dropped every native extension, `Myne.app` shipped with no
// `PlugIns/` and no `Watch/`, and the v0.8.2 TestFlight build was phone-only
// with every gate green and no compiler, test or guard reporting anything.
//
// The durable fix moves the project definition to a committed source of truth
// (`mobile/src-tauri/ios/project.yml`) that `mobile/scripts/ios-postinit.sh`
// re-applies, and wires that script into the package's `tauri` command so it
// cannot be skipped. This guard is the machine half:
//
//   1. the committed spec declares the three targets, the app-target embeds and
//      every committed source directory they compile;
//   2. the extension Info.plists take their version from build settings rather
//      than a hardcoded number (an app extension whose
//      CFBundleShortVersionString/CFBundleVersion differs from its containing
//      app is rejected by App Store validation);
//   3. the re-apply mechanism still exists and is still wired;
//   4. and, on a machine where the generated project exists, it has actually
//      been synced — the exact "I ran `tauri ios init` and forgot" state.
//
//   5. the App-Group identifier `group.md.myne.mobile` is byte-identical across
//      its three committed carriers: `share_import_ffi::APP_GROUP_ID`,
//      `ShareViewController.appGroupID` and the Share Extension's
//      `com.apple.security.application-groups` entitlement. The OS resolves the
//      shared container from this one string, so a drift makes the app and the
//      extension read two different directories and the shared file just
//      vanishes, with no build error on either side. The share extension itself
//      is deliberately unwired (needs the App Group capability on the App ID,
//      see `mobile/ios-share/README.md`), but these three strings ship in the
//      tree today and would be used the moment it is wired. When the extension
//      IS wired into `project.yml`, the app target must carry the group in
//      `entitlements.properties` — a `path`-only block overwrites the generated
//      entitlements with an empty `<dict/>` and the app silently loses it.
//
// Zero dependencies, hand-runnable: node scripts/check-ios-extensions.mjs

import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SPEC = "mobile/src-tauri/ios/project.yml";
const GEN = "mobile/src-tauri/gen/apple/project.yml";
const PLISTS = [
  "mobile/ios-widgets/MyneWidgets/Info.plist",
  "mobile/ios-watch/MyneWatch/Info.plist",
  "mobile/ios-watch/MyneWatchComplications/Info.plist",
];
const TARGETS = ["MyneWidgets", "MyneWatch", "MyneWatchComplications"];
// Only the widget is embedded via a target dependency. MyneWatch is built and
// copied by script phases instead (see below); embedding it as a dependency is
// the break this guard exists to prevent.
const EMBEDS = ["MyneWidgets"];
const SOURCE_DIRS = [
  ["mobile/ios-widgets/MyneWidgets", "../../../ios-widgets/MyneWidgets"],
  ["mobile/ios-watch/MyneWatch", "../../../ios-watch/MyneWatch"],
  ["mobile/ios-watch/MyneWatchComplications", "../../../ios-watch/MyneWatchComplications"],
  ["mobile/ios-watch/Shared", "../../../ios-watch/Shared"],
  ["mobile/ios-watch/Receiver", "../../../ios-watch/Receiver"],
];
const PLACEHOLDERS = [
  "__MYNE_DEVELOPMENT_TEAM__",
  "__MYNE_MARKETING_VERSION__",
  "__MYNE_CURRENT_PROJECT_VERSION__",
];

const failures = [];

/** Drop `#` comments so a placeholder named in prose is not read as a value. */
const stripComments = (text) => text.replace(/#[^\n]*/g, "");

function read(rel) {
  try {
    return readFileSync(join(repoRoot, rel), "utf8");
  } catch {
    // A guard that cannot find its input has stopped checking; saying so is the
    // only honest output (the failure check-embed-layout-drift records).
    failures.push(`${rel}: not found. This guard is looking at the wrong tree.`);
    return null;
  }
}

const targetRe = (t) => new RegExp(`^  ${t}:`, "m");

const spec = read(SPEC);
if (spec !== null) {
  for (const t of TARGETS) {
    if (!targetRe(t).test(spec)) {
      failures.push(
        `${SPEC}: target \`${t}\` is missing. Deleting it drops that native surface ` +
          `from the released app with no build error.`,
      );
    }
  }
  for (const t of EMBEDS) {
    if (!new RegExp(`- target: ${t}\\b`).test(spec)) {
      failures.push(
        `${SPEC}: the app target does not depend on \`${t}\`, so xcodegen emits no ` +
          `embed phase and the artifact ships without it.`,
      );
    }
  }
  for (const [dir, ref] of SOURCE_DIRS) {
    if (!spec.includes(`path: ${ref}`)) {
      failures.push(
        `${SPEC}: does not reference \`${ref}\`. The target would build with no ` +
          `sources, or the committed directory (${dir}) is dead.`,
      );
    }
    if (!existsSync(join(repoRoot, dir))) {
      failures.push(`${dir}: missing — ${SPEC} points at a directory that is not here.`);
    }
  }
  const specValues = stripComments(spec);
  for (const p of PLACEHOLDERS) {
    if (!specValues.includes(p)) {
      failures.push(
        `${SPEC}: placeholder \`${p}\` is gone. ios-postinit.sh substitutes it for the ` +
          `live build config; without it the version/team silently stops tracking.`,
      );
    }
  }
}

for (const rel of PLISTS) {
  const plist = read(rel);
  if (plist === null) continue;
  if (
    !plist.includes("<string>$(MARKETING_VERSION)</string>") ||
    !plist.includes("<string>$(CURRENT_PROJECT_VERSION)</string>")
  ) {
    failures.push(
      `${rel}: CFBundleShortVersionString/CFBundleVersion must be ` +
        `$(MARKETING_VERSION)/$(CURRENT_PROJECT_VERSION), not a hardcoded number. A ` +
        `hardcoded value drifts from the app's version and App Store validation ` +
        `rejects the bundle.`,
    );
  }
}

// ── 5. The App-Group identifier across its committed carriers ──────────────
// One string, three files, no compiler between them. See the header (clause 5).
const APP_GROUP_CARRIERS = [
  [
    "mobile/src-tauri/src/share_import_ffi.rs",
    /pub const APP_GROUP_ID: &str = "([^"]+)"/,
    "`pub const APP_GROUP_ID: &str`",
  ],
  [
    "mobile/ios-share/ShareExtension/ShareViewController.swift",
    /static let appGroupID = "([^"]+)"/,
    "`static let appGroupID`",
  ],
  [
    "mobile/ios-share/ShareExtension/ShareExtension.entitlements",
    /<key>com\.apple\.security\.application-groups<\/key>\s*<array>\s*<string>([^<]+)<\/string>/,
    "the `com.apple.security.application-groups` string",
  ],
];
const appGroups = [];
for (const [rel, re, what] of APP_GROUP_CARRIERS) {
  const text = read(rel);
  if (text === null) continue;
  const m = text.match(re);
  if (!m) {
    failures.push(
      `${rel}: could not find ${what} — did the App-Group identifier get renamed? ` +
        `The app and the Share Extension resolve their shared container from it.`,
    );
    continue;
  }
  appGroups.push([rel, m[1]]);
}
const groupId = appGroups.length > 0 ? appGroups[0][1] : null;
for (const [rel, value] of appGroups) {
  if (groupId !== null && value !== groupId) {
    failures.push(
      `App-Group drift: ${rel} has "${value}" but ${appGroups[0][0]} has "${groupId}". ` +
        `The OS resolves the shared container from this exact string, so the app and ` +
        `the extension would read two different directories and the shared file would ` +
        `vanish with no error on either side.`,
    );
  }
}
// The latent fourth carrier: only checked once the extension is actually wired
// into the committed spec (it is deliberately unwired today).
if (spec !== null && targetRe("MyneShareExtension").test(spec) && groupId !== null) {
  if (!stripComments(spec).includes(groupId)) {
    failures.push(
      `${SPEC}: wires \`MyneShareExtension\` but the app target does not declare the ` +
        `App-Group (${groupId}) in \`entitlements.properties\`. A \`path\`-only ` +
        `entitlements block makes xcodegen emit an empty <dict/> and the app silently ` +
        `loses the App-Group — see mobile/ios-share/README.md.`,
    );
  }
}

// The re-apply mechanism itself, so removing it fails here rather than at the
// next dropped release.
for (const rel of [
  "mobile/scripts/ios-postinit.sh",
  "mobile/scripts/tauri.sh",
  "mobile/scripts/ios-watch-build.sh",
  "mobile/scripts/ios-watch-embed.sh",
]) {
  if (!existsSync(join(repoRoot, rel))) failures.push(`${rel}: missing — the iOS re-apply/build mechanism is gone.`);
}
if (spec !== null) {
  // The watch is built by a script phase, NOT a target dependency: a dependency
  // would be compiled by `tauri ios build`'s `-sdk iphoneos` and die on every
  // watchOS WidgetKit API. Both halves of that mechanism have to stay wired.
  //
  // Scoped to the app target's body, because `- target: MyneWatch` legitimately
  // appears inside the MyneWatch target itself (its complication dependency).
  const clean = stripComments(spec);
  const appBody = clean.slice(clean.indexOf("myne-mobile_iOS:"));
  const appTarget = appBody.slice(0, appBody.indexOf("\n  MyneWidgets:"));
  if (/\n\s+- target: MyneWatch\b/.test(appTarget)) {
    failures.push(
      `${SPEC}: MyneWatch is a target dependency of the app again. Tauri's ` +
        `\`xcodebuild archive -sdk iphoneos\` will compile it against the iOS SDK ` +
        `and the complication fails ("only available in iOS 16+"). Build it via ` +
        `ios-watch-build.sh and embed via ios-watch-embed.sh instead.`,
    );
  }
  for (const marker of ["ios-watch-build.sh", "ios-watch-embed.sh"]) {
    if (!clean.includes(marker)) {
      failures.push(`${SPEC}: the watch build/embed wiring (\`${marker}\`) is gone.`);
    }
  }
}
const pkgText = read("mobile/package.json");
if (pkgText !== null) {
  let tauriScript;
  try {
    tauriScript = JSON.parse(pkgText).scripts?.tauri;
  } catch {
    failures.push("mobile/package.json: not valid JSON.");
  }
  if (tauriScript !== undefined && tauriScript !== "bash scripts/tauri.sh") {
    failures.push(
      `mobile/package.json: the \`tauri\` script is \`${tauriScript}\`, not ` +
        `\`bash scripts/tauri.sh\`. Without the wrapper, \`pnpm tauri ios build\` ` +
        `skips ios-postinit and ships a phone-only app after any init.`,
    );
  }
}

// On a machine that has run `tauri ios init`, the generated project must be
// synced. Absent (CI, fresh clone) is fine and is reported as such.
const genPath = join(repoRoot, GEN);
if (existsSync(genPath)) {
  let gen = "";
  try {
    gen = readFileSync(genPath, "utf8");
  } catch {
    failures.push(`${GEN}: present but unreadable.`);
  }
  if (stripComments(gen).includes("__MYNE_")) {
    failures.push(`${GEN}: contains an unsubstituted __MYNE_*__ placeholder — run \`pnpm --filter myne-mobile ios:postinit\`.`);
  }
  for (const t of TARGETS) {
    if (!targetRe(t).test(gen)) {
      failures.push(
        `${GEN}: target \`${t}\` is absent. The generated Xcode project has no ` +
          `${t}; a \`tauri ios init\` reset it. Run \`pnpm --filter myne-mobile ` +
          `ios:postinit\` (or any \`pnpm tauri ios …\` command in mobile/).`,
      );
    }
  }
}

if (failures.length > 0) {
  console.error("ios extensions: FAILED");
  for (const message of failures) console.error(`  - ${message}`);
  process.exit(1);
}

console.log(
  `ios extensions: ok (widgets + watch wired${
    existsSync(genPath) ? ", generated project synced" : ", generated project absent (CI/fresh clone)"
  })`,
);
